51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
69	    private Set<Pet> pets;
70	
71	    public String getAddress() {
72	        return this.address;
73	    }
74	
75	    public void setAddress(String address) {
76	        this.address = address;
77	    }
78	
79	    public String getCity() {
80	        return this.city;
81	    }
82	
83	    public void setCity(String city) {
84	        this.city = city;
85	    }
86	
87	    public String getTelephone() {
88	        return this.telephone;
89	    }
90	
91	    public void setTelephone(String telephone) {
92	        this.telephone = telephone;
93	    }
94	
95	    public String getEmail() {
96	        return this.email;
97	    }
98	
99	    public void setEmail(String email) {
100	        this.email = email == null ? null : email.toLowerCase();
101	    }
102	
103	    public LocalDate getRegistrationDate() {
104	        return this.registrationDate;
105	    }
106	
107	    public void setRegistrationDate(LocalDate registrationDate) {
108	        this.registrationDate = registrationDate;
109	    }
110	
111	    public String getCustomerCode() {
112	        return this.customerCode;
113	    }
114	
115	    public void setCustomerCode(String customerCode) {
116	        this.customerCode = customerCode;
117	    }
118	
119	    public String getHouseholdId() {
120	        return this.householdId;
121	    }
122	
123	    public void setHouseholdId(String householdId) {
124	        this.householdId = householdId;
125	    }
126	
127	    public Integer getNamesakeCount() {
128	        return this.namesakeCount;
129	    }
130	
131	    public void setNamesakeCount(Integer namesakeCount) {
132	        this.namesakeCount = namesakeCount;
133	    }
134	
135	    /**
136	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
137	     */
138	    public String getDisplayName() {
139	        return this.getLastName() + ", " + this.getFirstName();
140	    }
141	
142	    /**
143	     * The owner's initials: the upper-cased first letters of firstName and lastName,
144	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
145	     */
146	    public String getInitials() {
147	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
148	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
149	    }
150	
151	    /**
152	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
153	     * last two digits of the registrationDate year, e.g. {@code 'LON-SMI-0007-M26'}.
154	     */
155	    public String getMembershipNumber() {
156	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
157	    }
158	
159	    /** Fixed city-to-region table used to derive an owner's locality. */
160	    private static final Map<String, String> CITY_REGION = Map.of(
161	        "Sydney", "NSW",
162	        "Melbourne", "VIC",
163	        "Brisbane", "QLD");
164	
165	    /**
166	     * The owner's locality: the canonical region derived from the city using the fixed
167	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
168	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the table.
169	     */
170	    public String getLocality() {
171	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
172	    }
173	
174	    /**
175	     * The owner's membership tier: {@code 'SILVER'} when namesakeCount is 0 and an email is
176	     * present, otherwise {@code 'BRONZE'}.
177	     */
178	    public String getMembershipTier() {
179	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
180	        boolean hasEmail = this.email != null && !this.email.isEmpty();
181	        return unique && hasEmail ? "SILVER" : "BRONZE";
182	    }
183	
184	    protected Set<Pet> getPetsInternal() {
185	        if (this.pets == null) {
186	            this.pets = new HashSet<>();
187	        }
188	        return this.pets;
189	    }
190	
191	    protected void setPetsInternal(Set<Pet> pets) {
192	        this.pets = pets;
193	    }
194	
195	    public List<Pet> getPets() {
196	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
197	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
198	        return Collections.unmodifiableList(sortedPets);
199	    }
200	
201	    public void setPets(List<Pet> pets) {
202	        this.pets = new HashSet<>(pets);
203	    }
204	
205	    public void addPet(Pet pet) {
206	        getPetsInternal().add(pet);
207	        pet.setOwner(this);
208	    }
209	
210	    /**
211	     * Return the Pet with the given name, or null if none found for this Owner.
212	     *
213	     * @param name to test
214	     * @return true if pet name is already in use
215	     */
216	    public Pet getPet(String name) {
217	        return getPet(name, false);
218	    }
219	
220	    /**
221	     * Return the Pet with the given name, or null if none found for this Owner.
222	     *
223	     * @param name to test
224	     * @return true if pet name is already in use
225	     */
226	    public Pet getPet(String name, boolean ignoreNew) {
227	        name = name.toLowerCase();
228	        for (Pet pet : getPetsInternal()) {
229	            if (!ignoreNew || !pet.isNew()) {
230	                String compName = pet.getName();
231	                compName = compName.toLowerCase();
232	                if (compName.equals(name)) {
233	                    return pet;
234	                }
235	            }
236	        }
237	        return null;
238	    }
239	
240	    public Pet getPet(Integer petId) {
241	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
242	    }
243	
244	    @Override
245	    public String toString() {
246	        return new ToStringCreator(this)
247	
248	            .append("id", this.getId())
249	            .append("new", this.isNew())
250	            .append("lastName", this.getLastName())
251	            .append("firstName", this.getFirstName())
252	            .append("address", this.address)
253	            .append("city", this.city)
254	            .append("telephone", this.telephone)
255	            .append("email", this.email)
256	            .toString();
257	    }
258	}
