17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.Collection;
24	import java.util.List;
25	import java.util.Objects;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    private final AddressNormalizer addressNormalizer;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper,
75	                                 AddressNormalizer addressNormalizer) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	        this.addressNormalizer = addressNormalizer;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        String address = addressNormalizer.normalize(owner.getAddress());
114	        if (address.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        owner.setAddress(address);
118	        String telephone = toE164(owner.getTelephone());
119	        if (telephone == null) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setTelephone(telephone);
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        if (isTelephoneInUse(telephone)) {
127	            return new ResponseEntity<>(HttpStatus.CONFLICT);
128	        }
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
131	            return new ResponseEntity<>(HttpStatus.CONFLICT);
132	        }
133	        if (sharesHousehold) {
134	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
135	        }
136	        if (isCityAtCapacity(owner.getCity())) {
137	            return new ResponseEntity<>(HttpStatus.CONFLICT);
138	        }
139	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
140	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
141	        this.clinicService.saveOwner(owner);
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    /**
149	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
150	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
151	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
152	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
153	     */
154	    private String nextCustomerCode(String city, String lastName) {
155	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
156	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
157	        int sequence = (int) this.clinicService.findAllOwners().stream()
158	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
159	            .count() + 1;
160	        return String.format("%s-%s-%04d", city3, last3, sequence);
161	    }
162	
163	    /**
164	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
165	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
166	     */
167	    private boolean isCityAtCapacity(String city) {
168	        long count = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
170	            .count();
171	        return count >= 50;
172	    }
173	
174	    /**
175	     * The number of existing owners that already share the given firstName and lastName,
176	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
177	     * whitespace runs collapsed). Counted over the owners present before this create.
178	     */
179	    private int namesakeCount(String firstName, String lastName) {
180	        String candidateFirstName = normalizeName(firstName);
181	        String candidateLastName = normalizeName(lastName);
182	        return (int) this.clinicService.findAllOwners().stream()
183	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
184	                && normalizeName(existing.getLastName()).equals(candidateLastName))
185	            .count();
186	    }
187	
188	    /**
189	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
190	     * cannot form a valid E.164 number.
191	     *
192	     * <p>A leading '+' and country code are kept when present; otherwise country code
193	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
194	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
195	     * carry 8 to 15 digits after the '+'.
196	     */
197	    private String toE164(String telephone) {
198	        if (telephone == null) {
199	            return null;
200	        }
201	        boolean hasCountryCode = telephone.trim().startsWith("+");
202	        String digits = telephone.replaceAll("\\D", "");
203	        String e164;
204	        if (hasCountryCode) {
205	            e164 = digits;
206	        } else {
207	            if (digits.startsWith("0")) {
208	                digits = digits.substring(1);
209	            }
210	            e164 = "61" + digits;
211	        }
212	        if (e164.length() < 8 || e164.length() > 15) {
213	            return null;
214	        }
215	        return "+" + e164;
216	    }
217	
218	    /**
219	     * Whether any existing owner already holds the given telephone number. Both the
220	     * candidate and each stored number are compared in E.164 form, so the check does not
221	     * depend on how each was originally formatted.
222	     */
223	    private boolean isTelephoneInUse(String telephone) {
224	        return this.clinicService.findAllOwners().stream()
225	            .map(Owner::getTelephone)
226	            .filter(Objects::nonNull)
227	            .map(this::toE164)
228	            .filter(Objects::nonNull)
229	            .anyMatch(telephone::equals);
230	    }
231	
232	    /**
233	     * Whether any existing owner already shares a household with the candidate, i.e. has both
234	     * the same lastName and the same address. Both fields are compared case-insensitively and
235	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
236	     * trimmed), so the check does not depend on casing or spacing.
237	     */
238	    private boolean isHouseholdInUse(String lastName, String address) {
239	        String candidateLastName = normalizeName(lastName);
240	        String candidateAddress = addressNormalizer.normalize(address);
241	        return this.clinicService.findAllOwners().stream()
242	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
243	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
244	    }
245	
246	    /**
247	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
248	     * to a single space and lower-case. A null value normalizes to the empty string.
249	     */
250	    private String normalizeName(String value) {
251	        if (value == null) {
252	            return "";
253	        }
254	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
255	    }
256	
257	    /**
258	     * A stable shared identifier for the household formed by a given lastName and address.
259	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
260	     * lastName and address, so every owner sharing the same household is assigned the same
261	     * value regardless of the order in which they are created. Formatted as the first 12
262	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
263	     */
264	    private String householdId(String lastName, String address) {
265	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
266	        try {
267	            byte[] digest = MessageDigest.getInstance("SHA-256")
268	                .digest(key.getBytes(StandardCharsets.UTF_8));
269	            StringBuilder sb = new StringBuilder(digest.length * 2);
270	            for (byte b : digest) {
271	                sb.append(String.format("%02x", b));
272	            }
273	            return sb.substring(0, 12).toUpperCase();
274	        }
275	        catch (NoSuchAlgorithmException e) {
276	            throw new IllegalStateException("SHA-256 not available", e);
277	        }
278	    }
279	
280	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
